const rows = $input.all().map(i => i.json);
const total = rows[0]?.total_open ?? 0;
const newToday = rows[0]?.new_today ?? 0;

let html = `<h3>IT Ops – Offboarding Risk Daily Summary</h3>`;
html += `<p><b>${total}</b> asset(s) still marked in_use and held by a resigned employee`;
html += newToday > 0 ? ` (<b>${newToday}</b> new today).</p>` : `.</p>`;
html += `<table border="1" cellpadding="6" cellspacing="0"><tr><th>Resigned Employee</th><th>Assets Held</th></tr>`;
for (const r of rows) {
  html += `<tr><td>${r.employee_name}</td><td>${r.flagged}</td></tr>`;
}
html += `</table>`;
html += `<p>Reclaim these assets or update custody in the sheet. This detects only — nothing is changed automatically.</p>`;

return [{ json: { subject: `IT Ops Offboarding Risk Summary – ${total} flagged`, html } }];
